        getDateByTd : function(td){
            var index = td.get("index");
            var range = td.get("range");
            var date = this.date.clone();
            date.increment("day", parseInt(index) - 1) ;
            return Date.parse( date.clearTime().format("%Y-%m-%d") + " " + ( range == "am" ? "11:59:59" : "23:59:59" ) );  
        },
        triggerMouseEnter : function(td){
            if( this.getDateByTd( td ) < new Date() ){
                td.setStyle("cursor","default");
            }else{
                td.setStyle("cursor","pointer");
            }
        },
        triggerClick : function( td ){
            if( this.getDateByTd( td ) < new Date() ){
                this.cancelCurrentTd(); 
            }else{
                this.setCurrentTd( td );
            }
        },
        triggerDblclick : function( td, e ){
            var date = this.getDateByTd( td );
            if( date < new Date() ){ 
                this.app.notice("会议的时间不能早于现在", "error");
            }else{
                this.cancelCurrentTd(); 
                var range = td.get("range");
                var index = td.get("index");
                var room = td.get("room");
                //this.meetingMap.am.push(m);
                var dayObj = this.days[date.format("%Y%m%d")];
                var timeRange = [
                    Date.parse( date.format("%Y-%m-%d") + " " + WorkTimeRange[range][0] ),
                    Date.parse( date.format("%Y-%m-%d") + " " + WorkTimeRange[range][1] )
                ];
                var now = new Date();
                if( timeRange[0] < now )timeRange[0] = new Date().increment("hour",1);
                if( timeRange[1] < now )timeRange[1] = new Date().increment("hour",2);
                var usedRange = [];
                dayObj.meetingMap[range].each( function( meeting ){
                    if( meeting.data.room == room ){ 
                        var start = Date.parse( meeting.data.startTime );
                        var end = Date.parse( meeting.data.completedTime );
                        usedRange.push( [ start, end ] );
                    }
                })
                var availableRange = window.RangeArrayUtils.complementary( timeRange, usedRange, "date" );
                if( availableRange.length == 0 ){
                    var _self = this;
                    this.app.confirm("infor", e, "确认", "您所选的会议室在工作时间没有空闲,是否确定新建申请？", 380, 200, function(){
                        _self.addMeeting( room, null, td.get("roomName")  );
                    }, function(){
                        this.close();
                    });
                }else if( availableRange.length > 1 ){
                    var select = new window.TimeRangeSelect( { app: this.app }, {}, { 
                        timeRange : availableRange,
                        description : "请选择" + parseInt(date.format("%m")) + "月" +  
                            parseInt(date.format("%d")) + "日" + ( range == "am" ? "上午" : "下午") +"的时间范围" , 
                        onPostOk : function( range ){
                            this.addMeeting( room, range, td.get("roomName") )
                        }.bind(this)
                    })
                    select.edit();
                }else{
                    this.addMeeting( room, availableRange[0], td.get("roomName") )
                }
                //this.app.addMeeting();  
            }
        },
        addMeeting : function(room, range, roomName){ 
            debugger;
            if( range ){
                var processData = {
                    dateInput : range[0].format("%Y-%m-%d"),
                    beginTimeInput : range[0].format("%H:%M"),
                    endTimeInput : range[1].format("%H:%M"),
                    roomSelect : roomName,
                    room : room
                }
            }else{
                var processData = {
                    roomSelect : roomName,
                    room : room
                }
            }
            
            this.app.addMeeting(null, null, null, null, processData, true);
        },
        setTdStyle : function( td ){
            var index = td.get("index");
            var date = this.date.clone();
            date.increment("day", parseInt(index) - 1) ;
            if( date.clearTime() - new Date().clearTime() == 0 ){
                var range = td.get("range");
                var hour = new Date().getHours();
                if( hour < 12 && range == "am" ){
                    td.setStyle("background-color","#F8FBFF");  
                    return;
                }else if( hour >= 12 && range == "pm" ){
                    td.setStyle("background-color","#F8FBFF"); 
                    return;
                }
            }
            td.setStyle("background-color","#fff");
            return;
        },  
        setCurrentTd : function(td){
            td.setStyle("background-color","#fffdf2");
            if( this.currentSelectedTd ){
                //this.currentSelectedTd.setStyle("background-color", "#fff");
                this.setTdStyle( this.currentSelectedTd ); 
            }
            this.currentSelectedTd = td;
        },
        cancelCurrentTd : function(){
            if( this.currentSelectedTd ){
                this.setTdStyle( this.currentSelectedTd ); 
            }
            this.currentSelectedTd = null;
        }
    });
    
    o2.xApplication.Meeting.WeekView.Calendar.Day.implement({
        load : function(){
            this.color = "#666";
            //if(  this.type == "thisWeek" ){
            //}else if( this.type == "otherWeek" ){
            //    //this.color = "#ccc";
            //}
            
            this.meetingMap = {
                am : [],
                pm : []
            };
        
            this.day = this.date.getDate();
            this.month = this.date.getMonth();
            this.year = this.date.getYear();
    
            this.loadMeetings();
    
            this.roomMeetingObject = {};
    
            this.containerObject = {};
            this.calendar.calendarTable.getElements("td[index='"+ this.index +"']").each( function(td){
                if( !this.containerObject[ td.get("room") ] )this.containerObject[ td.get("room") ] = {};
                this.containerObject[ td.get("room") ][ td.get("range") ] = td;
            }.bind(this));
        },
        loadEmpty: function(){
            
        },
        _loadMeetings: function( isAll ){
            var y = this.date.getFullYear();
            var m = this.date.getMonth()+1;
            var d = this.date.getDate();
    
            this.app.actions[ isAll ? "listMeetingDayAll" : "listMeetingDay" ](y, m, d, function(json){
                var length = json.data.length;
                json.data.each(function(meeting, i){
                    if( !this.roomMeetingObject[ meeting.room ] ){
                        this.roomMeetingObject[ meeting.room ] = [];
                    }
                    this.roomMeetingObject[ meeting.room].push( meeting );
                }.bind(this));
    
                this.loadEmpty();
    
                this.loadRoomMeeting();
            }.bind(this));
        },
        loadRoomMeeting : function(){
            var meetingCount = 0;
    
            for( var key in this.roomMeetingObject ) { 
                debugger;
                var tdMap = this.containerObject[key];
                
                var contentNode_am = null, contentNode_pm = null;
                var meetingCount = this.roomMeetingObject[key].length;
                
                this.roomMeetingObject[key].each(function (meeting, idx) {
                    var range = this.getRange(meeting);
                    if( range.contains("am") ){
                        if( !contentNode_am ){
                            var td_am = tdMap["am"];
                            var node_am = new Element("div", {
                                //"styles": this.css["calendarTableCell_" + this.type]
                            }).inject(td_am);
                            contentNode_am = new Element("div", {"styles": this.css.dayContentNode}).inject(node_am);
                        }
                        var m = new o2.xApplication.Meeting.WeekView.Calendar.Day.Meeting(this, contentNode_am, meeting, meetingCount);
                        m.parentNode = node_am;
                        m.parentTd = td_am; 
                        this.meetings.push( m );
                        this.meetingMap.am.push(m);
                    }
                    if( range.contains("pm") ){
                        if( !contentNode_pm ){
                            var td_pm = tdMap["pm"];
                            var node_pm = new Element("div", {
                                //"styles": this.css["calendarTableCell_" + this.type]
                            }).inject(td_pm);
                            contentNode_pm = new Element("div", {"styles": this.css.dayContentNode}).inject(node_pm);
                        }
                        var m = new o2.xApplication.Meeting.WeekView.Calendar.Day.Meeting(this, contentNode_pm, meeting, meetingCount);
                        m.parentNode = node_pm;
                        m.parentTd = td_pm;
                        this.meetings.push( m );
                        this.meetingMap.pm.push(m);
                    }
                }.bind(this));
            }
        },
        getRange : function( meeting ){
            var start = Date.parse( meeting.startTime ).getHours();
            var end = Date.parse( meeting.completedTime ).getHours();
            if( start > 12 )return ["pm"];
            if( end <= 12 )return ["am"];
            return ["am","pm"]
        }
    });
    
    o2.xApplication.Meeting.WeekView.Calendar.Day.Meeting.implement({
        load: function(){
            this.nodeStyles =  this.css.meetingNode; //(this.day.type == "today") ? this.css.meetingNode_today :
            this.node = new Element("div", {
