this.define("searchTask", function(){
    var table = this.page.get("task_table").node.getElement("table");
    var infor = this.page.get("taskFinishInfor").node;

    var filterData = this.getTaskFilterData();
    this.action.listTaskFilter("(0)", 100, filterData, function(json){
        var cellStyles = {
            "height": "40px",
            "padding-left": "10px",
            "font-size": "16px",
            "cursor": "pointer"
        };
        if (json.data && json.data.length){
            table.setStyle("display", "table");
            infor.setStyle("display", "none");

            this.clearListTable(table);

            json.data.each(function(task){
                var row = table.insertRow(-1);
                row.addEvents({
                    "mouseover": function(){this.setStyles({"background": "#ffffff"});},
                    "mouseout": function(){this.setStyles({"background": "transparent"});},
                    "click": function(){
                        layout.desktop.openApplication(this.event, "process.Work", {
                            "workId": task.work
                        });
                    }.bind(this)
                });
                var cell = row.insertCell(-1).setStyles(cellStyles);
                cell.set("text", task.title);

                cell = row.insertCell(-1).setStyles(cellStyles);
                cell.set("text", task.processName);

                cell = row.insertCell(-1).setStyles(cellStyles);
                cell.set("text", task.startTime);

                cell = row.insertCell(-1).setStyles(cellStyles);
                cell.set("text", task.activityName);

            }.bind(this));

        }else{
            table.setStyle("display", "none");
            infor.setStyle("display", "blcok");
        }
    }.bind(this));
}.bind(this));

this.define("clearListTable", function(table){
