            "identity": identity,
            "latest": this.options.latest
        };
        if( this.workData ){
            data.data = this.workData;
        }

        if (!data.identity) {
            this.departmentSelArea.setStyle("border-color", "red");
            this.app.notice(this.lp.selectStartId, "error");
        } else {
            this.mask = new o2.widget.Mask({"style": "desktop"});
