            this.workAction.startWork(function (json) {
                this.mask.hide();

                this.close();

                this.afterStartProcess(json.data, data.title, this.process.name);

                //this.fireEvent("started", [json.data, data.title, this.process.name]);

                // this.app.refreshAll();
