        this.setSize();
        if( this.options.listFilterCount ){
            if( this.options.listFilterCount=="listTaskFilterCount" ) var ta = this.action.TaskAction;
            if( this.options.listFilterCount=="listTaskCompletedFilterCount" ) var ta = this.action.TaskCompletedAction;
            var data_par = {};
            data_par["processList"] = this.options.processList;
            ta.filterAttributeFilter(
                data_par,
                function( json ){ 
                    if (!this.options.processList) this.setOptions(this.page.get("processSelect"), json.data[this.options.filter[0]]);
                    this.setOptions(this.page.get("unitSelect"), json.data[this.options.filter[1]]);
                    this.setOptions(this.page.get("dateSelect"), json.data[this.options.filter[2]]);
