        var appNode = this.page.app.content;
        var appNodeSize = appNode.getSize();

        var navi_y = appNodeSize.y;
        if (this.page.get("leftNavi")){
            var leftNaviNode = this.page.get("leftNavi").node; 
            navi_y = navi_y - 80 - 20 - 20 - 4 - 20;
            leftNaviNode.setStyle( "height", navi_y )
        }

        if (this.page.get("div_taskArea")){ 
            y = navi_y - 120;
            this.page.get("div_taskArea").node.setStyles({
                "height": y,
                "overflow" : "auto"
            });
        }

        if (this.page.get("div_taskCompletedArea")){
             y = navi_y - 120;
            this.page.get("div_taskCompletedArea").node.setStyles({
                "height": y,
                "overflow" : "auto"
            });
        }

        var dovumentViewList = this.page.get("dovumentViewList");
        if( dovumentViewList ){
            var list_y = appNodeSize.y - 80 - 20 - 40 - 10 - 20;
            dovumentViewList.node.setStyles({
                "height": list_y,
                "overflow" : "auto"
            });
