    },
    setOptions: function(module, ops){
        module.resetOption();
        ops.each(function(op){
            module.addOption(op.name, op.value);
        }.bind(this));
    },
    searchTask: function(){
        var filterData = this.getTaskFilterData();

        if(this.options.listFilter=="listTaskFilter") var ta = this.action.TaskAction
        if(this.options.listFilter=="listTaskCompletedFilter") var ta = this.action.TaskCompletedAction

        ta.listNextWithFilter(//平台封装好的方法
            "(0)",100,//uri的参数
            filterData,//body请求参数
            function( json ){ //服务调用成功的回调函数, json为服务传回的数据
                var cellStyles = {
                    "height": "40px",
                    "padding-left": "10px",
                    "font-size": "14px",
                    "color" : "#666",
                    "cursor": "pointer",
                    "border-bottom":"1px solid #ddd"
                };
                if (json.data && json.data.length){
                    this.table.setStyle("display", "table");
                    this.infor.setStyle("display", "none");

                    this.clearListTable(this.table);

                    json.data.each(function(task){
                        var row = this.table.insertRow(-1);
                        row.addEvents({
                            "mouseover": function(){this.setStyles({"background": "#ffffff"});},
                            "mouseout": function(){this.setStyles({"background": "transparent"});},
                            "click": function(){
                                if (task.workCompleted){
                                    _self.form.openWork("", task.workCompleted);
                                }else{
                                    _self.form.openWork(task.work);
                                }

                            }.bind(this)
                        });
                        var cell = row.insertCell(-1).setStyles({
                            "height": "40px",
                            "padding-left": "10px",
                            "font-size": "16px",
                            "cursor": "pointer",
                            "border-bottom":"1px solid #ddd"
                        });
                        cell.set("text", task[this.options.fields[0]] || "无项目名称");

                        cell = row.insertCell(-1).setStyles(cellStyles);
                        cell.set("text", task[this.options.fields[1]]);

                        cell = row.insertCell(-1).setStyles(cellStyles);
                        cell.set("text", task[this.options.fields[2]]);

                        cell = row.insertCell(-1).setStyles(cellStyles);
                        cell.set("text", task[this.options.fields[3]]);

                    }.bind(this));
                }else{
                    this.table.setStyle("display", "none");
                    this.infor.setStyle("display", "block");
                }
            }.bind(this),
            function( json ){

            }.bind(this),
            false //同步执行 
        );
    },
    clearListTable: function(table){
        while(table.rows.length>1) table.deleteRow(table.rows.length-1);
    },

    getTaskFilterData: function(){
        var process = this.page.get("processSelect").getData();
        process = (process=="none") ? "" : process;

        var unit = this.page.get("unitSelect").getData();
        unit = (unit=="none") ? "" : unit;

        var startdate = this.page.get("dateSelect").getData();
        startdate = (startdate=="none") ? "" : startdate;

        var activity = this.page.get("activitySelect").getData();
        activity = (activity=="none") ? "" : activity;

        var key = this.page.get("taskKeyWord").getData();

        return {
            "processList": (process) ? [process] : this.options.processList,
            "creatorUnitList":(unit) ? [unit] : [],
            "startTimeMonthList":(startdate) ? [startdate] : [],
            "activityNameList":(activity) ? [activity] : [],
            "key":key
        };
    },
    resetSearch: function(){
        this.page.get("processSelect").setData("none");
        this.page.get("unitSelect").setData("none");
        this.page.get("dateSelect").setData("none");
        this.page.get("activitySelect").setData("none");
        this.page.get("taskKeyWord").setData("");
        this.searchTask();
    }
});

