            this.changeWeekNext();
        }.bind(this))

        this.titleLeftNode = new Element("div",{
            styles : this.css.titleLeftNode,
            text : "上一周"
        }).inject(this.titleNode);
        this.titleLeftNode.addEvent("click", function(){
            this.changeWeekPrev();
        }.bind(this)) 

        var t = parseInt( this.baseDate.format("%m") ) + "月" + parseInt( this.baseDate.format("%d") ) + "日";
        var text = t + "，本周";
        this.titleContentNode = new Element("div",{
            styles : this.css.titleContentNode,
            text : text
        }).inject(this.titleNode);
    },
    changeWeekPrev: function(){
        this.date.decrement("week", 1);
        this.baseDate = this.date;
        var t =  parseInt( this.baseDate.format("%m") ) + "月" + parseInt( this.baseDate.format("%d") ) + "日";
        var weekNum = this.getWeekNumber( this.baseDate  );
        var text;
        if( weekNum == this.currentWeekNum ){
            text = t + "，本周";
        }else if( weekNum == this.nextWeekNum ){
            text = t + "，下周";
        }else if( weekNum == this.prevWeekNum ){
            text = t + "，上周";
        }else{
           text = t + "，第" + weekNum + "周"; 
        }
        this.titleContentNode.set("text", text);
        this.reload();
    },
    changeWeekNext: function(){ 
        this.date.increment("week", 1);
        this.baseDate = this.date;
        var t =  parseInt( this.baseDate.format("%m") ) + "月" + parseInt( this.baseDate.format("%d") ) + "日";
        var weekNum = this.getWeekNumber( this.baseDate  );
        var text;
        if( weekNum == this.currentWeekNum ){
            text = t + "，本周";
        }else if( weekNum == this.nextWeekNum ){
            text = t + "，下周";
        }else if( weekNum == this.prevWeekNum ){
            text = t + "，上周";
        }else{
           text = t + "，第" + weekNum + "周"; 
        }
        this.titleContentNode.set("text", text);
        this.reload();
    },
    getWeekBeginDate: function( d ){
        var date = d.clone();

        var decrementDay = ( 7 + d.getDay() - parseInt( this.weekBegin ) ) % 7;

        return date.decrement("day", decrementDay);
    },
    getRoom : function( roomid ){
        return this.rooms[ roomid ];
    },
    getTdByRoomAndRange : function( roomid, range, index ){
        var room = this.rooms[ roomid ];
        if( range == "am" ){
            return room.td_list_am[index]
        }else{
            return room.td_list_pm[index]
        }
    },
    getWeekNumber: function(d){
        // Create a copy of this date object
        var target  = d.clone();

        var dayNr   =  ( 7 + d.getDay() - parseInt( this.weekBegin ) ) % 7;

        target.setDate(target.getDate() - dayNr + 3);

        var firstThursday = target.valueOf();

        target.setMonth(0, 1);
        if (target.getDay() != 4) {
            target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7);
        }

        return 1 + Math.ceil((firstThursday - target) / 604800000); // 604800000 = 7 * 24 * 3600 * 1000
    }
});

MeetingForMobile.Room = new Class({
    initialize: function( parent, data, buliding){
        this.parent = parent;
        this.css = parent.css;
