            }).inject(this.descriptNode);
        }

        if( this.data.capacity ){
            this.titleCountNode = new Element("div.titleCountNode", {
                "styles": inforStyles,
                "text" :  "容纳" + this.data.capacity + "人"
            }).inject(this.descriptNode);
        }
    },
    loadCalendar : function(){
        this.calendarTable = new Element("table", {
            "styles": this.css.calendarTable,
            "height": "100%",
            "border": "0",
            "cellPadding": "0",
            "cellSpacing": "0"
        }).inject(this.calendarNode);

        this.loadTableHead();
        this.loadTableBody();
    },
    loadTableHead : function(){
         var d = this.parent.date.clone();
        var today = new Date();
        var todayStr = today.format("%Y%m%d");

        if( !this.tableHead ){
            var head = this.tableHead = new Element("tr", {
                "styles" : this.css.calendarTableTitleTr
            }).inject( this.calendarTable );

            var th = new Element("th", {
                "styles" : this.css.calendarTableTh
            }).inject(head);
            th.setStyles({
                "width":"20px",
                "min-width" : "auto" 
            });

            for( var i=0; i<7; i++ ) {
                var index = (  i + parseInt( this.parent.weekBegin ) ) % 7;
                var styles;
                if( d.format("%Y%m%d") == todayStr ){
                    styles = this.css.calendarTableTh_today;
                }else{
                    styles = (d < today) ? this.css.calendarTableTh_pre :  this.css.calendarTableTh
                }
                var th = new Element("th", {
                    "styles": styles,
                    text: this.parent.lp.weekArr[index] // + "(" + d.format("%m.%d") + ")"
                }).inject(head);
                d.increment("day", 1);
            }
        }else{
            this.tableHead.getElements("th").each( function( th, i ){
                if( i == 0 || i == 1 )return;

                var styles; 
                if( d.format("%Y%m%d") == todayStr ){
                    styles = this.css.calendarTableTh_today;
                }else{
                    styles = (d < today) ? this.css.calendarTableTh_pre :  this.css.calendarTableTh
                }
                th.setStyles( styles );
                var index = (  i - 1 + parseInt( this.parent.weekBegin ) ) % 7;
                th.set("text", this.parent.lp.weekArr[index] ); //+ "(" + d.format("%m.%d") + ")");
                d.increment("day", 1);
            }.bind(this))
        }
    },
    loadTableBody : function(){
        var _self = this;
        this.td_list_am = [];

        var tr = this.tr_am = new Element( "tr").inject( this.calendarTable );

        new Element( "td" , {
            "tdType" : "am",
            "text" : "上午",
            "styles" : this.css.td
        }).inject( tr );

        for( var i=0; i<7; i++ ){
            td = new Element( "td" , {
                "tdType" : "meeting",
                "range" : "am",
                "index" : i+1,
                "styles" : this.css.td
            }).inject( tr );
            this.td_list_am.push( td );
            td.addEvent("click", function(ev){
                _self.triggerClick( this, ev );
            }.bind(td));
            this.setTdStyle( td );    
        }

        this.td_list_pm = [];
        var tr = this.tr_pm= new Element( "tr").inject( this.calendarTable );
        new Element( "td" , {
            "tdType" : "pm",
            "text" : "下午",
            "styles" : this.css.td
        }).inject( tr );
        for( var i=0; i<7; i++ ){ 
             td = new Element( "td" , {
                "tdType" : "meeting",
                "range" : "pm",
                "index" : i+1,
                "styles" : this.css.td
            }).inject( tr );
            this.td_list_pm.push( td );
            td.addEvent("click", function(ev){
                _self.triggerClick( this, ev );
            }.bind(td));
             this.setTdStyle( td );    
        }

    },
    setTdStyle : function( td ){  
        var index = td.get("index");
        var date = this.parent.date.clone();
        date.increment("day", parseInt(index) - 1) ;
        var d = date.clearTime();
        var n = new Date().clearTime();
        if( d - n == 0 ){
            var range = td.get("range");
            var hour = new Date().getHours();
            if( hour < 12 && range == "am" ){
                td.setStyle("background-color","#F8FBFF");  
                return;
            }else if( hour >= 12 && range == "pm" ){
                td.setStyle("background-color","#F8FBFF"); 
                return;
            }
        }else if( d - n < 0 ){
            td.setStyle("background-color","#eee");  
        }else{
            td.setStyle("background-color","#fff");
        }
        return;
    },
    getDateByTd : function(td){
        var index = td.get("index");
        var range = td.get("range");
        var date = this.parent.date.clone();
        date.increment("day", parseInt(index) - 1) ;
        return Date.parse( date.clearTime().format("%Y-%m-%d") + " " + ( range == "am" ? "11:59:59" : "23:59:59" ) );  
    },
    triggerClick : function(td, e){
        var date = this.getDateByTd( td );
        if( date < new Date() ){ 
            //this.parent.emv.page.app.notice("会议的时间不能早于现在", "error");
        }else{
            var _self = this;
            var text = "您是否要预定该会议室?";
            this.parent.emv.page.app.confirm("infor", e, "预定会议室确认", text, 250, 150, function(){
                _self.addMeeting( date );
                this.close();
            }, function(){
                this.close();
            });
        }
    },
    addMeeting : function(date){
        if( date ){
            var processData = { 
                dateInput : date.format("%Y-%m-%d"),
                roomSelect : this.data.name,
                room : this.data.id
            }
            // var processData = {
            //     dateInput : range[0].format("%Y-%m-%d"),
            //     beginTimeInput : range[0].format("%H:%M"),
            //     endTimeInput : range[1].format("%H:%M"),
            //     roomSelect : this.data.name,
            //     room : this.data.id
            // }
        }else{
            var processData = {
                roomSelect : this.data.name,
                room : this.data.id
            }
        }

        this.parent.emv.startWork( processData );
    }

})


MeetingForMobile.MeetingList = new Class({
    initialize: function( parent ){
        this.css = parent.css;
        this.parent = parent;
        this.isAll = true;
        this.load();
        this.meetings = [];
    },
    load : function(){
        var _self = this;
        var date = this.parent.date.clone();

        for( var i=0; i<7; i++ ){ 
            if( i!== 0 ) date.increment("day",1);

            var y = date.getFullYear();
            var m = date.getMonth()+1;
            var d = date.getDate();

            this.parent.actions[ this.isAll ? "listMeetingDayAll" : "listMeetingDay" ](y, m, d, function(json){
                var length = json.data.length;
                var roomMeetingObject = {};
                json.data.each(function(meeting ){
                    if( !roomMeetingObject[ meeting.room ] ){
                        roomMeetingObject[ meeting.room ] = [];
                    }
                    roomMeetingObject[ meeting.room].push( meeting );
                });

                _self.loadRoomMeeting(this, roomMeetingObject);
            }.bind(i));
        }

    },
    destroy : function(){
        while( this.meetings.length > 0 ){
            this.meetings.shift().destroy();
        }
        this.meetings = [];
    },
    loadRoomMeeting : function(index, roomMeetingObject){
        var meetingCount = 0;

        for( var key in roomMeetingObject ) {  

            var td_pm = null;
            var td_am = null;
            var contentNode_am = null;
            var contentNode_pm = null;
            var room = null;
            var meetingCount = roomMeetingObject[key].length;

            roomMeetingObject[key].each(function (meeting, idx) {
                var room = this.parent.getRoom( key );
                var range = this.getRange(meeting);
                if( range.contains("am") ){
                    if( !contentNode_am ){
                        td_am = this.parent.getTdByRoomAndRange( key, "am", index );
                        var node_am = new Element("div", {
                        }).inject(td_am);
                        contentNode_am = new Element("div", {"styles": this.css.dayContentNode}).inject(node_am);
                    }
                    var m = new MeetingForMobile.Meeting(this, contentNode_am, meeting, meetingCount, room, td_am);
                    m.parentNode = node_am;
                    m.parentTd = td_am;
                    this.meetings.push( m );
                    // this.meetingMap.am.push(m);
                }
                if( range.contains("pm") ){
                    if( !contentNode_pm ){
                        td_pm = this.parent.getTdByRoomAndRange( key, "pm", index );
                        var node_pm = new Element("div", {
                        }).inject(td_pm);
                        contentNode_pm = new Element("div", {"styles": this.css.dayContentNode}).inject(node_pm);
                    }
                    var m = new MeetingForMobile.Meeting(this, contentNode_pm, meeting, meetingCount, room, td_pm);
                    m.parentNode = node_pm;
                    m.parentTd = td_pm;
                    this.meetings.push( m );
                    // this.meetingMap.pm.push(m);
                }
            }.bind(this));
        }
    },
    getRange : function( meeting ){
        var start = Date.parse( meeting.startTime ).getHours();
        var end = Date.parse( meeting.completedTime ).getHours();
        if( start > 12 )return ["pm"];
        if( end <= 12 )return ["am"];
        return ["am","pm"]
    }
})


