this.define("loadMeeting", function(){
    //this.target.node.setStyle("height",document.body.getSize().y);

    var container = this.page.get("div_meetingArea").node;
    container.setStyle("background-color","#eee");
    container.empty();
    var app = this.page.app;
    var scrollNode = app.node;
    this.meeting = new o2.xApplication.Meeting.MainInContainer2( app.desktop, { 
        "sideBarEnable" : false, 
        "settingEnable" : false,
        "onQueryLoad" : function(){
            debugger;
            if(this.meeting){
                if( this.meeting.css && this.meeting.css.contentNode_inContainer ){
                    this.meeting.css.contentNode_inContainer["margin-top"] = "0px";
                }
                if( this.meeting.contentNode ){
                    this.meeting.contentNode.setStyle("margin-top","0px"); 
                }
                if( this.meeting.css && this.meeting.css.topMenu ){
                    this.meeting.css.topMenu.position = "static";
                }
                if(this.meeting.topMenu){
                    this.meeting.topMenu.setStyle("position","static");
                }
            }
        }.bind(this)
    }, container, app.content , scrollNode );
    debugger;
    this.meeting.load();

    this.resizeContainer();
})

this.define("initMeeting", function(){
    debugger;
    var container = this.page.get("div_meetingArea").node;
    var appContent = container.getParent(".MWF_dialod_content");
    if( appContent ){
        var scrollNode = appContent.getFirst();
        scrollNode.setStyle("overflow","visible");
        scrollNode.setStyle("height","100%");
    }
    this.resizeContainer();
    this.page.app.addEvent("resize", function(){
        this.resizeContainer();
        debugger; 
        this.calendar.fireEvent("resize");
    }.bind(this) )
})

this.define("rendingPage", function(){
    this.setStyle();
    this.setSize();
})

this.define("setStyle", function(){
    if (this.page.get("leftNavi")) {
        var divs = this.page.get("leftNavi").node.getChildren();
        divs.setStyle("color", "#333333");
        divs.setStyle("background-color", "#e7eef5");
        divs.each( function(div){
            div.addEvents({
                mouseover : function( ev ){
                    var bgc = this.getStyle("background-color");
                    if( bgc != "#ffffff" )this.setStyles({ "background-color" : "#E6E6E6"  })
                }.bind(div),
                mouseout : function( ev ){
                    var bgc = this.getStyle("background-color");
                    if( bgc != "#ffffff" )this.setStyles({ "background-color" : "#e7eef5" })
                }.bind(div)
            })
        }.bind(this))
    }

    if (this.page.get("dovumentViewList")) {
        this.page.get("dovumentViewList").node.setStyles( {
            "background-color": "#e7eef5"
        });
    }
})

this.define("setSize", function(){
    if( this.isFirstLoad )return;

    var appNode = this.page.app.content;
    var appNodeSize = appNode.getSize();

    // var pageNode = this.page.node();
    // var topNaviNode = pageNode.getFirst();
    if (this.page.get("leftNavi")){
        var leftNaviNode = this.page.get("leftNavi").node; 
        var navi_y = appNodeSize.y - 80 - 20 - 20 - 4 - 20;
        leftNaviNode.setStyle( "height", navi_y )
    }

    // var div_new_message = this.page.get("div_new_message");
    // if( div_new_message ){
    //     var list_y = appNodeSize.y - 200;
    //     div_new_message.node.setStyles({
    //         "height": list_y,
    //         "overflow" : "auto"
    //     });
    // }

    var dovumentViewList = this.page.get("dovumentViewList");
    if( dovumentViewList ){
        var list_y = appNodeSize.y - 80 - 20 - 40 - 10 - 20;
        dovumentViewList.node.setStyles({
            "height": list_y,
            "overflow" : "auto"
        });
    }
    this.isFirstLoad = true;
})

